R=Path(__file__).resolve().parents[1];E=R/'experiments';D=E/'wbuart_feature_alias_classes_v1_2026-10-20'
def read(p):return json.loads(Path(p).read_text())
def main():
 p=D/'classes_frozen.json';v=read(p);assert len(v['rows'])==18 and not v['target_labels_read'];assert all(sha(path)==h for path,h in v['bindings'].items());workflow=E/'wbuart_native_evaluation_v1_2026-10-20/workflow.json';specs=read(workflow)['comparisons'];predictions=read(E/'wbuart_graph_signal_learning_v1_2026-10-20/predictions_frozen.json')['rows'];actual=read(E/'wbuart_half_decision_v1_2026-10-20/evaluation_v1.json')['rows'];rows=[];bindings={str(q):sha(q) for q in [p,workflow,Path(__file__),R/'tools/feature_alias_bounds_v1.py',E/'wbuart_graph_signal_learning_v1_2026-10-20/predictions_frozen.json',E/'wbuart_half_decision_v1_2026-10-20/evaluation_v1.json']}
 for row in v['rows']:
  sp=Path(next(r['specification'] for r in specs if r['case']==row['case']));s=read(sp);labels={int(n):c for n,c in read(s['label_physical_audit'])['node_occupancy'].items()};groups=read(row['classes']);counts=[(len(g['RRs']),sum(labels.get(n,0) for n in g['RRs'])) for g in groups];assert all(labels.get(n,0) in [0,1] for g in groups for n in g['RRs']);bound=limits(counts);r=next(r for r in predictions if r['case']==row['case'] and r['mode']==row['mode']);ids=read(r['resource_ids']);soft=read(r['probabilities']);lookup=dict(zip(ids,soft));assert all(len({lookup[n] for n in g['RRs']})==1 for g in groups);observed=next(r for r in actual if r['case']==row['case'] and r['mode']==row['mode']);actual_errors=observed['point_confusion']['FP']+observed['point_confusion']['FN'];assert actual_errors>=bound['minimum_binary_errors'] and observed['soft_ROC_AUC']<=float(bound['maximum_ROC_AUC'])+1e-15;oracle_counts={n:choice for g,choice in zip(groups,bound['majority_decisions']) for n in g['RRs']};oracle_rates={n:rate for g,rate in zip(groups,bound['oracle_rates']) for n in g['RRs']};assert sum(oracle_counts[n]!=labels.get(n,0) for n in ids)==bound['minimum_binary_errors'];assert abs(auc([oracle_rates[n] for n in ids],[labels.get(n,0) for n in ids])-float(bound['maximum_ROC_AUC']))<=1e-15
  domain=read(s['domain_proof']);directory=Path(s['domain_proof']).parent;resources=[json.loads(x) for x in (directory/'resources.jsonl').read_text().splitlines()];bins=read(directory/'spatial_bins.json');truth=scores(resources,bins,labels);methods={'label_majority_oracle':oracle_counts,'previous_native':{int(n):c for n,c in read(s['source_frame'])['ledger'].items()},'original_H0_raw_min_on':{int(n):c for n,c in read(s['predictions']['raw_min_on']['frame'])['ledger'].items()}};metrics={name:measure(scores(resources,bins,data),truth,domain) for name,data in methods.items()};checks={name:numeric_comparison(metrics['label_majority_oracle'],metrics[name]) for name in ['previous_native','original_H0_raw_min_on']};cert=Path(row['classes']).parent/'label_counts_bound_witness.json';cert.write_text(json.dumps({'label_dependent':True,'admitted_predictor':False,'classes':[{'class':g['class'],'resources':n,'positive_labels':positive,'majority':choice,'oracle_rate':str(rate)} for g,(n,positive),choice,rate in zip(groups,counts,bound['majority_decisions'],bound['oracle_rates'])]},separators=(',',':'))+'\n');rows.append({**row,'minimum_binary_errors':bound['minimum_binary_errors'],'minimum_binary_error_fraction':bound['minimum_binary_errors']/len(ids),'maximum_ROC_AUC':str(bound['maximum_ROC_AUC']),'conflicting_classes':bound['conflicting_groups'],'resources_in_conflicting_classes':bound['resources_in_conflicting_groups'],'actual_half_errors':actual_errors,'actual_soft_ROC_AUC':observed['soft_ROC_AUC'],'actual_error_above_lower_bound':actual_errors-bound['minimum_binary_errors'],'label_majority_original_gate_diagnostic':all(checks.values()),'label_majority_metrics':metrics,'bound_witness':str(cert)});bindings[str(cert)]=sha(cert)
  for q in [sp,Path(s['label_physical_audit']),Path(s['domain_proof']),directory/'resources.jsonl',directory/'spatial_bins.json',Path(s['source_frame']),Path(s['predictions']['raw_min_on']['frame'])]:bindings[str(q)]=sha(q)
  print('FEATURE_ALIAS_BOUND',row['case'],row['mode'],len(groups),bound['minimum_binary_errors'],actual_errors,flush=True)
 out=D/'evaluation_v1.json';assert not out.exists();out.write_text(json.dumps({'status':'ALL18_FIXED_FEATURE_BINARY_AND_ROC_LIMITS_EVALUATED','rows':rows,'bindings':bindings,'scope':'Target-dependent percase optimal lookup on fixed equal-feature classes only. Cannot predict unseen labels or certify generalization, ranking optimum, capacity, routing or original predictor admission. Majority minimizes Hamming, not original four-metric gates.'},indent=2)+'\n')
if __name__=='__main__':main()
